return [{
  json: {
    schema_version: '1.0.0',
    connector_id: '30_ALERT_MONITOR',
    connector_name: 'UW-Issaquah Alert Monitor',
    connector_version: 'v0003',
    lane: '30_ALERT_MONITOR',
    run_id: '30_ALERT_MONITOR-' + new Date().toISOString().replace(/[:.]/g, '') + '-001',
    run_stamp: new Date().toISOString().replace(/[:.]/g, ''),
    generated_at: new Date().toISOString(),
