const helpers = this.helpers;
let alertedIds = [];
try {
  const item = $input.first();
  if (item.binary && item.binary.data) {
    const buffer = await helpers.getBinaryDataBuffer(0, 'data');
    const parsed = JSON.parse(buffer.toString('utf8'));
    if (parsed && Array.isArray(parsed.alerted_event_ids)) alertedIds = parsed.alerted_event_ids;
  }
} catch (error) {
  alertedIds = [];
}
const stableAliases = [
  {
    stable_event_id: '01_ROUTE_CONDITIONS:KC-03:trail_closure:east_lake_sammamish_trail_louis_thompson_to_inglewood_2026-06-01',
    legacy_prefix: '01_ROUTE_CONDITIONS:KC-03:hash_'
  }
];
const migratedFromLegacy = [];
for (const alias of stableAliases) {
  if (!alertedIds.includes(alias.stable_event_id) && alertedIds.some((id) => typeof id === 'string' && id.startsWith(alias.legacy_prefix))) {
    alertedIds.push(alias.stable_event_id);
    migratedFromLegacy.push(alias.stable_event_id);
  }
}
return [{ json: { kind: 'alerted_state', alerted_event_ids: Array.from(new Set(alertedIds)), migrated_legacy_event_ids: migratedFromLegacy } }];

