const items = $input.all().map(i => i.json);
const run = $('Initialize Run Metadata').first().json;
const stateItem = items.find(i => i.kind === 'alerted_state') || { alerted_event_ids: [] };
const laneItems = items.filter(i => i.kind === 'lane');
const alertedSet = new Set(stateItem.alerted_event_ids || []);

const newEventsByLane = [];
const allCurrentEventIds = new Set();
for (const item of laneItems) {
  if (!item.available || !item.data) continue;
  const events = (item.data.events || item.data.deduplicated_events || []);
  for (const event of events) {
    const eventId = event && event.event_id;
    if (!eventId) continue;
    allCurrentEventIds.add(eventId);
    if (!alertedSet.has(eventId)) {
      newEventsByLane.push({
        lane_id: item.lane_id,
        lane_label: item.lane_label,
        event_id: eventId,
        event_type: event.event_type || null,
        status: event.status || null,
        severity: event.severity || null,
        summary: event.summary || event.title || null,
        details: event.details || event.description || null
      });
    }
  }
}

const hasNewEvents = newEventsByLane.length > 0;
const updatedAlertedIds = Array.from(new Set([...alertedSet, ...allCurrentEventIds]));

return [{ json: {
  run_id: run.run_id,
  generated_at: run.generated_at,
  output_root: run.output_root,
  has_new_events: hasNewEvents,
  new_events_by_lane: newEventsByLane,
  updated_alerted_state: { alerted_event_ids: updatedAlertedIds, updated_at: run.generated_at },
  summary_message: hasNewEvents
    ? (newEventsByLane.length + ' new route-relevant event(s) detected.')
    : 'No new route-relevant events since last check.'
} }];

const helpers = this.helpers;
const item = $input.first().json;
const filePath = item.output_root + '/alerts/last_alerted_state.json';
const buffer = Buffer.from(JSON.stringify(item.updated_alerted_state, null, 2), 'utf8');
const binary = await helpers.prepareBinaryData(buffer, 'last_alerted_state.json', 'application/json');
return [{ json: { file_path: filePath }, binary: { data: binary } }];

