} }];

const item = $input.first().json;
if (!item.has_new_events) return [];
return [{ json: item }];

const item = $input.first().json;
const lines = item.new_events_by_lane.map((e) => {
  return '[' + e.lane_label + '] ' + (e.summary || e.event_type || e.event_id) +
    (e.severity ? ' (severity: ' + e.severity + ')' : '') +
    (e.details ? '\n    ' + e.details : '');
});
const subject = 'UW-Issy Route Alert: ' + item.new_events_by_lane.length + ' new event(s)';
const message = 'New route-relevant event(s) detected on the UW-Issaquah route monitor:\n\n' +
  lines.join('\n\n') +
  '\n\nRun: ' + item.run_id + '\nGenerated: ' + item.generated_at;
return [{ json: { subject, message } }];

